    size_t len = (*env)->GetStringLength(env, string);
    size_t bytes = (*env)->GetStringUTFLength(env, string);
    char* chars = (char*) malloc(bytes + 1);
    (*env)->GetStringUTFRegion(env, string, 0, len, chars);
    chars[bytes] = 0;
    return chars;
}

